```svelte
<script>
	let { object = { count: 0 } } = $props();

	const state = $state({ object })

	$effect(() => {
		console.log('in state', state.object.count);
	});
	$effect(() => {
		console.log('in object', object.count);
	});
</script>

<button onclick={() => state.object.count += 1}>
